'use client';

import { useState } from 'react';
import { useAccount, useWriteContract } from 'wagmi';

const CONTRACT_ADDRESS = '0x50aEd6E73a526E9497a200A92e8bd0D68F838f02';

export default function CookingGame() {
  const { address, isConnected } = useAccount();
  const [gameId, setGameId] = useState('game001');
  const [ingredients, setIngredients] = useState('鸡蛋\n面粉\n牛奶\n巧克力');
  const [answer, setAnswer] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState('');

  const { writeContract } = useWriteContract();

  const createGame = async () => {
    if (!isConnected) {
      alert('请先点击 Connect Wallet 连接钱包');
      return;
    }
    setLoading(true);
    setResult('正在创建游戏...');
    try {
      await writeContract({
        address: CONTRACT_ADDRESS as `0x${string}`,
        abi: [], // 暂时简化，后续可补充完整ABI
        functionName: 'add_game',
        args: [gameId, address || '', new Date().toISOString().slice(0,10), 3600, ingredients.split('\n').filter(i => i.trim())],
      });
      setResult('✅ 创建游戏请求已发送！请在 GenLayer Studio 中查看执行结果');
    } catch (error: any) {
      setResult('❌ 创建失败: ' + error.message);
    }
    setLoading(false);
  };

  const joinGame = async () => {
    if (!isConnected) {
      alert('请先点击 Connect Wallet 连接钱包');
      return;
    }
    setLoading(true);
    setResult('正在提交菜谱...');
    try {
      await writeContract({
        address: CONTRACT_ADDRESS as `0x${string}`,
        abi: [],
        functionName: 'join_game',
        args: [gameId, address || '', answer, 85],
      });
      setResult('✅ 菜谱提交成功！AI 正在打分，请在 Studio 查看结果');
    } catch (error: any) {
      setResult('❌ 提交失败: ' + error.message);
    }
    setLoading(false);
  };

  return (
    <div className="min-h-screen bg-black text-white p-8">
      <div className="max-w-5xl mx-auto">
        <div className="text-center mb-12">
          <h1 className="text-6xl font-bold mb-4">🍳 GenLayer 烹饪游戏</h1>
          <p className="text-xl text-gray-400">AI 驱动的烹饪比赛 • 使用 GenLayer Intelligent Contract</p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* 创建游戏卡片 */}
          <div className="bg-zinc-900 p-8 rounded-3xl">
            <h2 className="text-3xl font-semibold mb-6 flex items-center gap-3">
              <span>1️⃣</span> 创建新游戏
            </h2>
            <input
              type="text"
              value={gameId}
              onChange={(e) => setGameId(e.target.value)}
              className="w-full p-4 bg-zinc-800 border border-zinc-700 rounded-2xl mb-6 text-lg"
              placeholder="游戏ID (例如: game001)"
            />
            <textarea
              value={ingredients}
              onChange={(e) => setIngredients(e.target.value)}
              className="w-full p-4 bg-zinc-800 border border-zinc-700 rounded-2xl h-40 mb-6 text-lg"
              placeholder="食材列表（每行一个）"
            />
            <button
              onClick={createGame}
              disabled={loading}
              className="w-full bg-orange-600 hover:bg-orange-700 py-5 rounded-2xl font-bold text-xl disabled:opacity-50"
            >
              {loading ? '创建中...' : '创建游戏'}
            </button>
          </div>

          {/* 加入游戏卡片 */}
          <div className="bg-zinc-900 p-8 rounded-3xl">
            <h2 className="text-3xl font-semibold mb-6 flex items-center gap-3">
              <span>2️⃣</span> 加入游戏并提交菜谱
            </h2>
            <input
              type="text"
              value={gameId}
              onChange={(e) => setGameId(e.target.value)}
              className="w-full p-4 bg-zinc-800 border border-zinc-700 rounded-2xl mb-6 text-lg"
              placeholder="游戏ID"
            />
            <textarea
              value={answer}
              onChange={(e) => setAnswer(e.target.value)}
              className="w-full p-4 bg-zinc-800 border border-zinc-700 rounded-2xl h-52 mb-6 text-lg"
              placeholder="在这里写下你的完整菜谱..."
            />
            <button
              onClick={joinGame}
              disabled={loading}
              className="w-full bg-orange-600 hover:bg-orange-700 py-5 rounded-2xl font-bold text-xl disabled:opacity-50"
            >
              {loading ? '提交中...' : '提交菜谱'}
            </button>
          </div>
        </div>

        {result && (
          <div className="mt-10 p-8 bg-zinc-900 rounded-3xl text-xl">
            {result}
          </div>
        )}

        <div className="mt-12 text-center text-gray-500">
          合约地址：<span className="font-mono text-orange-400">{CONTRACT_ADDRESS}</span><br />
          当前钱包：{address ? address : '未连接，请点击右上角 Connect Wallet'}
        </div>
      </div>
    </div>
  );
}